local s=function(R)local N,k=R[#R],""for Z=1,#N,1 do k=k..N[R[Z]]end return k end local R={}R.__index=R function R.new(N)return setmetatable({name=N},R)end function R.describe(R)return R.name..(" with area "..string.format("%.2f",R:area()))end function R.area(R)return 0 end local N=setmetatable({},{__index=R})N.__index=N function N.new(k)local Z=R.new("circle")Z.radius=k return setmetatable(Z,N)end function N.area(R)return math.pi*R.radius^2 end local k=setmetatable({},{__index=R})k.__index=k function k.new(N,Z)local U=R.new("rect")U.width,U.height=N,Z return setmetatable(U,k)end function k.area(R)return R.width*R.height end local Z={}Z.__index=Z Z.__len=nil function Z.new()return setmetatable({first=1;last=0;items={}},Z)end function Z.push(N,R)N.last=N.last+1 N.items[N.last]=R end function Z.pop(R)if R.first>R.last then return nil end local N=R.items[R.first]R.items[R.first]=nil R.first=R.first+1 return N end function Z.size(R)return(R.last-R.first)+1 end local U=Z.new()U:push(N.new(2))U:push(k.new(3,4))U:push(R.new("blob"))while U:size()>0 do print((U:pop()):describe())end local function J(R)local N={}for R in(R:lower()):gmatch("%a+")do N[R]=((N[R]or 0))+1 end local k={}for R in pairs(N)do k[#k+1]=R end table.sort(k,function(R,k)if N[R]~=N[k]then return N[R]>N[k]end return R<k end)local Z={}for R=1,math.min(3,#k),1 do Z[#Z+1]=k[R]..(":"..N[k[R]])end return table.concat(Z,", ")end print(J("To be, or not to be, that is the question: to be wise is to be"))